package org.sleepwell.app;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.os.*;import android.view.*;import android.view.inspector.WindowInspector;import android.widget.TextView;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.junit.Test;import java.io.File;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;
/** Private configuration and fake scheduling only. No alarm runtime or hardware. */
public final class SunriseTimeFlowTest {
    final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();final UiDevice d=UiDevice.getInstance(i);volatile Activity current;final List<Activity> owned=new CopyOnWriteArrayList<>();
    interface Check{boolean ready()throws Exception;}void await(String action,Check check)throws Exception{long until=SystemClock.elapsedRealtime()+12000;while(!check.ready()){if(SystemClock.elapsedRealtime()>until)throw new AssertionError("Sunrise fixture: "+action);Thread.sleep(30);}}
    View root(){for(View view:WindowInspector.getGlobalWindowViews())if(view.hasWindowFocus()&&view.isAttachedToWindow()&&view.getContext().getPackageName().equals(c.getPackageName()))return view;return null;}
    View find(View view,String text){if(view==null)return null;if(text.contentEquals(view.getContentDescription()==null?"":view.getContentDescription())||view instanceof TextView&&text.contentEquals(((TextView)view).getText()))return view;if(view instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View found=find(group.getChildAt(n),text);if(found!=null)return found;}return null;}
    Rect target(String text){Rect[] result={null};i.runOnMainSync(()->{View view=find(root(),text);while(view!=null&&!view.isClickable())view=view.getParent() instanceof View?(View)view.getParent():null;if(view==null||!view.isEnabled())return;Rect rect=new Rect();if(!view.getGlobalVisibleRect(rect)||rect.height()!=view.getHeight()||rect.width()!=view.getWidth()){view.requestRectangleOnScreen(new Rect(0,0,view.getWidth(),view.getHeight()),false);return;}if(rect.height()<Design.dp(c,48)||rect.width()<Design.dp(c,48))return;int[] position=new int[2];view.getLocationOnScreen(position);result[0]=new Rect(position[0],position[1],position[0]+view.getWidth(),position[1]+view.getHeight());});return result[0];}
    void frame()throws Exception{CountDownLatch latch=new CountDownLatch(1);i.runOnMainSync(()->{View view=root();assertNotNull("Focused app window",view);view.getViewTreeObserver().registerFrameCommitCallback(latch::countDown);view.invalidate();});assertTrue(latch.await(5,TimeUnit.SECONDS));}
    void click(String text)throws Exception{await("click "+text,()->target(text)!=null);frame();Rect rect=target(text);assertNotNull(text,rect);assertTrue(d.click(rect.centerX(),rect.centerY()));}
    void shown(String text)throws Exception{await("show "+text,()->{boolean[] found={false};i.runOnMainSync(()->found[0]=find(root(),text)!=null);return found[0];});}
    void input(String desc,String value)throws Exception{UiObject2 input=d.wait(Until.findObject(By.desc(desc)),5000);assertNotNull(desc,input);input.setText(value);boolean[] ime={false};i.runOnMainSync(()->{WindowInsets insets=root().getRootWindowInsets();ime[0]=insets!=null&&insets.isVisible(WindowInsets.Type.ime());});if(ime[0]){assertTrue(d.pressBack());await("closed input keyboard",()->{boolean[] closed={false};i.runOnMainSync(()->{WindowInsets insets=root().getRootWindowInsets();closed[0]=insets==null||!insets.isVisible(WindowInsets.Type.ime());});return closed[0];});}}
    File folder(){File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());return folder;}void capture(String name)throws Exception{frame();assertTrue(d.takeScreenshot(new File(folder(),"sunrise-time-"+name+".png")));}
    void launch(Alarm alarm)throws Exception{Activity a=i.startActivitySync(new Intent(c,AlarmEditorActivity.class).putExtra("alarm",alarm.json().toString()).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));current=a;await("editor focus",a::hasWindowFocus);shown("Edit alarm");}
    void recreate(String label)throws Exception{Activity before=current;i.runOnMainSync(before::recreate);await("recreated focus",()->current!=before&&current.hasWindowFocus());shown(label);}
    @Test public void manualCoordinatesFallbackConsentCancelSaveRecreationAndReopenUseRealPrivateState()throws Exception{assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",d.executeShellCommand("getprop ro.kernel.qemu").trim());Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks observer=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){assertTrue(a instanceof AlarmEditorActivity||a instanceof SunriseTimeActivity);owned.add(a);}public void onActivityResumed(Activity a){current=a;}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(observer);
        try(AlarmSkipFixture f=new AlarmSkipFixture()){try{Alarm initial=f.load();initial.enabled=false;try(Store store=f.open()){store.save(initial);}launch(initial);click("Time basis");shown("Alarm time basis");click("Sunrise time");click("Use time basis");shown("Sunrise time error");capture("invalid");input("Sunrise latitude","40.72");input("Sunrise longitude","-74.02");click("Sunrise offset");click("-30 min");click("Confirm sunrise fallback");click("Calculate next sunrise");shown("Calculated sunrise preview");capture("configured");recreate("Alarm time basis");assertEquals("40.72",d.findObject(By.desc("Sunrise latitude")).getText());assertEquals("-74.02",d.findObject(By.desc("Sunrise longitude")).getText());assertTrue(d.findObject(By.desc("Confirm sunrise fallback")).isChecked());shown("Calculated sunrise preview");capture("recreated");click("Use time basis");shown("Edit alarm");assertNull(f.load().solar);recreate("Edit alarm");Activity editor=current;click("Save alarm");await("saved editor finished",editor::isDestroyed);assertEquals(1,f.schedules);Alarm saved=f.load();assertFalse(saved.enabled);assertEquals(new SunriseSchedule(40.72,-74.02,-30,true).key(),saved.solar.key());launch(saved);click("Time basis");shown("Alarm time basis");assertEquals("40.72",d.findObject(By.desc("Sunrise latitude")).getText());click("Calculate next sunrise");shown("Calculated sunrise preview");capture("reopened");click("Clock time");click("Back");shown("Edit alarm");click("Save alarm");await("cancel preserved editor finished",()->current.isDestroyed());assertNotNull(f.load().solar);launch(f.load());click("Time basis");click("Clock time");click("Use time basis");shown("Edit alarm");click("Save alarm");await("clock basis editor finished",()->current.isDestroyed());assertNull(f.load().solar);assertEquals(3,f.schedules);
            }catch(Exception|AssertionError problem){try{d.takeScreenshot(new File(folder(),"sunrise-time-failure.png"));d.dumpWindowHierarchy(new File(folder(),"sunrise-time-failure.xml"));}catch(Exception diagnostic){problem.addSuppressed(diagnostic);}throw problem;}finally{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});await("owned activities destroyed",()->owned.stream().allMatch(Activity::isDestroyed));}}
        finally{app.unregisterActivityLifecycleCallbacks(observer);}}
}
